/// Create a `PageMetadata` from a JSON string. Returns null on failure.
/// # Safety
/// JSON string must be valid UTF-8 and null-terminated.
/// Returned handle must be freed with `cberg_page_metadata_free`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn cberg_page_metadata_from_json(json: *const c_char) -> AlefHandle {
    catch_ffi_panic(0, || {
        clear_last_error();
        if json.is_null() {
            set_last_error(1, "Null pointer passed for JSON string");
            return 0;
        }
        // SAFETY: null check above guarantees json is a valid pointer; string is valid UTF-8 from caller.
        let c_str = match unsafe { CStr::from_ptr(json) }.to_str() {
            Ok(s) => s,
            Err(_) => {
                set_last_error(1, "Invalid UTF-8 in JSON string");
                return 0;
            }
        };
        match serde_json::from_str::<crawlberg::PageMetadata>(c_str) {
            Ok(val) => match insert_handle(val) {
                Ok(handle) => handle,
                Err(error) => {
                    set_handle_error(&error);
                    0
                }
            },
            Err(e) => {
                set_last_error(2, &e.to_string());
                0
            }
        }
    })
}

/// Serialize a `PageMetadata` to a JSON string. Returns null on failure.
/// # Safety
/// `handle` must be a valid, non-zero handle returned by a `cberg` function.
/// The returned string must be freed with `cberg_free_string`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn cberg_page_metadata_to_json(handle: AlefHandle) -> *mut c_char {
    catch_ffi_panic(std::ptr::null_mut(), || {
        clear_last_error();
        if handle == 0 {
            set_last_error(ALEF_INVALID_HANDLE_ERROR, "zero is not a valid handle");
            return std::ptr::null_mut();
        }
        match with_handle::<crawlberg::PageMetadata, _>(handle, serde_json::to_string) {
            Err(error) => {
                set_handle_error(&error);
                std::ptr::null_mut()
            }
            Ok(Err(error)) => {
                set_last_error(2, &error.to_string());
                std::ptr::null_mut()
            }
            Ok(Ok(s)) => match CString::new(s) {
                Ok(cs) => cs.into_raw(),
                Err(e) => {
                    set_last_error(2, &e.to_string());
                    std::ptr::null_mut()
                }
            },
        }
    })
}

